#!/usr/bin/env bash
# Post or preview a benchmark update comment for the tracking issue.

set -euo pipefail

ISSUE_NUMBER="28"
REPO="${GITHUB_REPOSITORY:-}"
SUMMARY_FILE=""
DASHBOARD_FILE=""
OUTPUT_FILE=""
DRY_RUN=0
RUN_URL=""

usage() {
    cat <<'EOF'
Usage: scripts/post-gym-results.sh --summary PATH [options]

Options:
  --summary PATH      Required summary markdown generated by `skwaq gym eval`
  --dashboard PATH    Optional dashboard markdown to append
  --issue NUMBER      GitHub issue number to comment on (default: 28)
  --repo OWNER/REPO   Repository slug (default: infer from GITHUB_REPOSITORY or git remote)
  --run-url URL       Optional workflow run URL to include in the comment
  --output PATH       Write the rendered comment body to PATH
  --dry-run           Print the rendered comment body instead of posting it
  -h, --help          Show this help text
EOF
}

infer_repo() {
    if [[ -n "${REPO}" ]]; then
        return
    fi

    if ! git_remote=$(git config --get remote.origin.url 2>/dev/null); then
        return
    fi

    REPO=$(python - "$git_remote" <<'PY'
import re
import sys

remote = sys.argv[1].strip()
match = re.search(r'github\.com[:/](.+?)(?:\.git)?$', remote)
if match:
    print(match.group(1))
PY
)
}

while [[ $# -gt 0 ]]; do
    case "$1" in
        --summary)
            SUMMARY_FILE="$2"
            shift 2
            ;;
        --dashboard)
            DASHBOARD_FILE="$2"
            shift 2
            ;;
        --issue)
            ISSUE_NUMBER="$2"
            shift 2
            ;;
        --repo)
            REPO="$2"
            shift 2
            ;;
        --run-url)
            RUN_URL="$2"
            shift 2
            ;;
        --output)
            OUTPUT_FILE="$2"
            shift 2
            ;;
        --dry-run)
            DRY_RUN=1
            shift
            ;;
        -h|--help)
            usage
            exit 0
            ;;
        *)
            echo "Unknown option: $1" >&2
            usage >&2
            exit 1
            ;;
    esac
done

if [[ -z "${SUMMARY_FILE}" ]]; then
    echo "--summary is required" >&2
    usage >&2
    exit 1
fi

if [[ ! -f "${SUMMARY_FILE}" ]]; then
    echo "Summary file not found: ${SUMMARY_FILE}" >&2
    exit 1
fi

if [[ -n "${DASHBOARD_FILE}" && ! -f "${DASHBOARD_FILE}" ]]; then
    echo "Dashboard file not found: ${DASHBOARD_FILE}" >&2
    exit 1
fi

infer_repo

if [[ -z "${RUN_URL}" && -n "${GITHUB_SERVER_URL:-}" && -n "${GITHUB_REPOSITORY:-}" && -n "${GITHUB_RUN_ID:-}" ]]; then
    RUN_URL="${GITHUB_SERVER_URL}/${GITHUB_REPOSITORY}/actions/runs/${GITHUB_RUN_ID}"
fi

body_file=$(mktemp)
cleanup() {
    rm -f "${body_file}"
}
trap cleanup EXIT

{
    echo "## Gym benchmark update"
    echo
    if [[ -n "${GITHUB_SHA:-}" ]]; then
        echo "- Commit: \`${GITHUB_SHA:0:7}\`"
    fi
    if [[ -n "${RUN_URL}" ]]; then
        echo "- Run: ${RUN_URL}"
    fi
    if [[ -n "${GITHUB_WORKFLOW:-}" ]]; then
        echo "- Workflow: ${GITHUB_WORKFLOW}"
    fi
    echo
    cat "${SUMMARY_FILE}"
    if [[ -n "${DASHBOARD_FILE}" ]]; then
        echo
        echo "## Dashboard"
        echo
        cat "${DASHBOARD_FILE}"
    fi
} > "${body_file}"

if [[ -n "${OUTPUT_FILE}" ]]; then
    cp "${body_file}" "${OUTPUT_FILE}"
fi

if [[ "${DRY_RUN}" -eq 1 ]]; then
    cat "${body_file}"
    exit 0
fi

if [[ -z "${REPO}" ]]; then
    echo "Unable to determine repository slug; pass --repo OWNER/REPO" >&2
    exit 1
fi

gh issue comment "${ISSUE_NUMBER}" --repo "${REPO}" --body-file "${body_file}"
